import{K as t,Pa as r,Y as a,ea as o}from"./chunk-D575DXPO.js";var l=[{slug:"chalkbox",screenshots:[{src:"/assets/projects/chalkbox/chalkbox-landing.webp",alt:"ChalkBox public landing page with teacher-first lesson planning and verified demo access",caption:"Live product \xB7 Public landing page",width:1265,height:712},{src:"/assets/projects/chalkbox/chalkbox-lesson-workflow.webp",alt:"ChalkBox verified Class 8 Science lesson showing the timed teaching flow and classroom delivery modes",caption:"Verified public demo \xB7 Lesson planning and classroom workflow",width:1265,height:712}],displayTitle:"ChalkBox",subtitle:"AI-Powered Teacher Lesson Planning & Classroom Assistant",summary:"Turn textbook material or a teaching topic into a classroom-ready lesson, with source-grounded retrieval, safety audits and Hindi support.",primaryTechnologies:["React 19","TypeScript","Supabase","Google Gemini","RAG"],visualIndex:0,title:"ChalkBox \u2014 AI-Powered Teacher Lesson Planning & Classroom Assistant",category:"Generative AI \xB7 RAG \xB7 Education Technology",filter:"AI/ML",short:"ChalkBox",description:"An AI-powered teacher lesson-planning and classroom-delivery platform that transforms textbook material and teaching topics into structured, classroom-ready lessons with source-grounded RAG, safety-aware generation and cloud persistence.",technologies:["React 19","TypeScript","Vite","Tailwind CSS","Supabase","PostgreSQL","pgvector","Google Gemini","RAG","Generative AI","Cloudflare Pages"],status:"Omnikon 2026 \xB7 Finalist \xB7 Rank 9 / 126",github:"https://github.com/harshawardhanchitnis/ChalkBox-AI-Lesson-Planning-for-Real-Classrooms",live:"https://chalkbox-harshlabs.pages.dev",pipeline:["Private textbook / teaching topic","Source-grounded retrieval","Generation + safety audit","Classroom delivery","Cloud lesson library"],sections:[{title:"Problem / Motivation",text:"Teachers need a direct path from textbook material and teaching topics to lessons they can use in real classrooms. ChalkBox brings planning, source grounding and classroom delivery into one teacher-first workflow."},{title:"Key Engineering Decisions",items:["Teacher-first delivery: Textbook Mode starts from curriculum material; Topic Mode starts from a teaching request. Full Lesson, Start Class, Quick Teach and Present Mode turn the result into a usable classroom sequence.","Private RAG: PDFs are stored privately, extracted into page-based chunks and indexed with pgvector. Retrieval is scoped to the selected teacher-owned textbook, with source-page provenance retained in lesson sections.","Separate generation and audit: generated lessons pass through science, classroom-feasibility and safety checks. Deterministic preflight rules complement the independent audit stage.","Owner-scoped persistence: Supabase RLS restricts plans, notes and textbook data to their owner. Gemini and service-role credentials stay in server-side Edge Functions rather than the browser."]},{title:"Trade-offs & Reliability",text:"Prepared, verified demo lessons keep the teaching workflow available without a live AI call. Live Topic generation offers flexibility but depends on provider latency and quotas. Private Textbook generation adds ingestion, retrieval and auditing steps in exchange for traceable source grounding."},{title:"Testing / Validation",text:"The repository documents release checks for build/type validation, authentication, owner-scoped persistence, private textbook provenance, Hindi rendering, responsive layouts and classroom-safety prompts. The public landing page and verified lesson flow were directly inspected for this portfolio; these screenshots are product evidence, not an independent certification of all backend controls."},{title:"Limitations & Future Work",text:"The documented product scope is Class 8\u201310 Science, with Hindi support for classroom content. Additional subjects, broader curriculum adapters, resumable large-document ingestion and further language support remain future work."},{title:"Lessons Learned",text:"The project documentation highlights three lessons: usable teaching flow matters alongside model output quality; provenance is most useful when teachers can see the supporting pages; and safety guidance needs to remain visible across every delivery mode."},{title:"Architecture",text:"A React 19 and TypeScript frontend built with Vite and Tailwind CSS is hosted on Cloudflare Pages. Google Gemini powers generation. Supabase provides authentication, private storage and a cloud lesson library, with PostgreSQL and pgvector supporting source-grounded retrieval. Row Level Security protects access to stored data."},{title:"Key Features",items:["Textbook Mode and Topic Mode for different planning inputs.","Full Lesson, Start Class, Quick Teach and Present Mode for planning and delivery.","Hindi classroom support.","Private textbook upload with source-grounded Retrieval-Augmented Generation and page provenance.","Cloud lesson persistence with Supabase authentication, private storage and Row Level Security."]},{title:"Engineering Challenges & Implementation",text:"Source grounding and classroom safety are central to the workflow. Generation and audit stages support science/classroom safety validation, while page provenance connects retrieved material to its textbook source."},{title:"Recognition",text:"Team HarshLabs reached the Top 10 Final at Omnikon National AI/ML Hackathon 2026, ranking 9th among 126 teams. ChalkBox was a finalist project."}]},{slug:"smart-parking",displayTitle:"Smart Parking Intelligence",subtitle:"Artificial Intelligence Based Smart Parking System",summary:"Analyse parking images and fixed-camera video using four-corner geometry, occupancy evidence and temporal reasoning.",primaryTechnologies:["FastAPI","Next.js","OpenCV","ONNX Runtime","YOLO11n-pose"],visualIndex:1,title:"Artificial Intelligence Based Smart Parking System",category:"Artificial Intelligence \xB7 Computer Vision",filter:"AI/ML",short:"Parking intelligence",description:"A computer-vision parking intelligence platform for images and fixed-camera video, combining perspective-aware parking-space localisation, occupancy inference, vehicle reasoning, temporal processing, analytics and reporting.",technologies:["Python","FastAPI","Next.js","React","TypeScript","OpenCV","PyTorch","ONNX Runtime","MobileNetV3-Small","YOLO11n-pose","SQLite","FFmpeg"],status:"190 backend tests passing",github:"https://github.com/harshawardhanchitnis/Artificial-Intelligence-Based-Smart-Parking-System-",pipeline:["Image / fixed-camera video","Four-corner localisation","Occupancy + scene evidence","Temporal processing","Analytics + reports"],sections:[{title:"Problem / Motivation",text:"Parking intelligence requires reliable space geometry as well as occupancy estimates. Perspective, vehicle placement and camera movement can make a simple binary classification unreliable."},{title:"My Contribution",text:"Built the parking-intelligence platform described in the project repository: model-development and inference workflows, image/video analysis, geometry and occupancy reasoning, and the interface for history, diagnostics and reports. The repository identifies Harshawardhan Chitnis as the project author."},{title:"Key Engineering Decisions",items:["Four independent corners represent trapezoidal parking bays under perspective, where even an oriented rectangle cannot follow the projected boundary. YOLO11n-pose balances this geometry with CPU latency, model size and ONNX deployment.","PyTorch is used for model development, training and export; production FastAPI inference uses ONNX Runtime, keeping the serving graph separate from training dependencies.","Vacant, Occupied and Uncertain states combine MobileNetV3-Small evidence with full-scene vehicle reasoning and geometry confidence. The system can abstain when reliable parking geometry is unavailable.","Stable layouts are calibrated across fixed-camera frames and reused during temporal video analysis. Camera drift triggers revalidation rather than continued use of stale geometry."]},{title:"Trade-offs",text:"The documented comparison found stronger geometry from Keypoint R-CNN, but at a substantially higher CPU deployment cost. The selected pose model favors a smaller deployable system. Reusing a calibrated layout reduces repeated localisation work, but requires camera-stability checks and recalibration."},{title:"Testing / Validation",text:"Project documentation reports 190 backend tests passing, alongside frontend lint/type/build checks, video playback checks and occupancy accounting validation. Benchmark mode retains dataset-defined spaces and protected holdout boundaries; product mode reasons about the wider visible scene. These tests are backend validation, not a claim of universal scene accuracy."},{title:"Limitations & Future Work",text:"Current support covers images and prerecorded fixed-camera video in a local-first prototype. Geometry recall depends on camera and dataset diversity; parking-specific two-wheeler validation remains limited. Production live RTSP ingestion, moving-camera support and cloud multi-tenant deployment are not claimed."},{title:"Architecture",text:"Next.js, React and TypeScript provide the interface, with a Python/FastAPI backend. The deployed parking-space localiser is YOLO11n-pose with four independent parking-space corners. MobileNetV3-Small combines with geometric and scene evidence for occupancy inference. PyTorch supports model development, training and export. Production backend inference uses ONNX Runtime; OpenCV and FFmpeg support media processing, with SQLite for persistence."},{title:"Key Features",items:["Four-corner perspective-aware parking geometry and per-space occupancy inference.","Vacant, Occupied and Uncertain states.","Full-scene vehicle detection, parking-area reasoning and vehicle-to-space association.","Automatic fixed-camera calibration and camera drift detection.","Temporal processing for video, analytics, history and diagnostics.","Downloadable reporting and safe abstention when geometry is unreliable."]},{title:"Engineering Challenges & Implementation",text:"The pipeline treats geometry reliability as a prerequisite for a confident occupancy decision. Scene evidence, vehicle association and temporal processing support interpretation across fixed-camera video; uncertain geometry can lead to abstention rather than an unsupported prediction."},{title:"Results / Evaluation",text:"Current project documentation reports 190 backend tests passing. This describes automated backend validation; occupancy accuracy depends on the input scene and geometry reliability."}]},{slug:"privacy-aware-face-analytics",github:"https://github.com/harshawardhanchitnis/Privacy-Aware-Real-Time-Multi-Face-Detection-Tracking-Analytics-Platform",displayTitle:"Privacy-Aware Face Analytics",subtitle:"Privacy-Aware Real-Time Multi-Face Detection, Tracking & Analytics Platform",summary:"Detect and track multiple faces with anonymisation, versioned inference and a reproducible model-to-analytics lifecycle.",primaryTechnologies:["Python","TensorFlow","OpenCV","MLflow","Docker"],visualIndex:2,title:"Privacy-Aware Real-Time Multi-Face Detection, Tracking & Analytics Platform",category:"Computer Vision \xB7 Privacy \xB7 ML Engineering",filter:"AI/ML",short:"Privacy-aware vision",description:"An end-to-end computer-vision platform for real-time multi-face detection, tracking and behavioural analytics with privacy-preserving anonymisation, reproducible ML lifecycle management and live/historical analytics.",technologies:["Python","TensorFlow","OpenCV","MLflow","Docker","REST APIs","Computer Vision"],status:"Privacy-preserving inference",pipeline:["Ingest + preprocess","Train + evaluate","Compare + promote","Versioned REST inference","Live + historical analytics"],sections:[{title:"Problem / Motivation",text:"Real-time face analytics needs to connect detection and tracking with privacy-preserving inference, a reproducible model lifecycle and usable operational insights."},{title:"Engineering Approach",items:["Detection and tracking feed anonymised inference and behavioural analytics, keeping privacy-aware processing part of the inference workflow.","MLflow experiment tracking and model comparison connect training to controlled promotion; versioned REST inference exposes the promoted model through a Docker-based deployment.","Persistent analytics support both live operational views and historical inspection, rather than leaving predictions as a transient camera overlay."]},{title:"Validation Scope",text:"The documented workflow includes model training, evaluation, comparison and promotion. No quantitative detection, latency or privacy-validation results are published in this case study, so no accuracy or performance figure is claimed."},{title:"Architecture",text:"Python, TensorFlow and OpenCV support multi-face detection, tracking and behavioural analytics. Data ingestion and preprocessing lead into training and evaluation. MLflow tracks experiments and model comparisons, supporting controlled model promotion. Docker containerisation and a versioned REST API connect inference to the backend and persistent analytics."},{title:"Key Features",items:["Real-time multi-face detection and tracking.","Behavioural analytics with anonymisation and privacy-preserving inference.","Data ingestion, preprocessing, model training and evaluation.","MLflow experiment tracking, model comparison and controlled model promotion.","Docker containerisation and versioned REST API inference.","Backend integration, persistent analytics and live/historical dashboard insights."]},{title:"Engineering Challenges & Implementation",text:"The system connects a controlled training-to-inference lifecycle with privacy-aware processing. Versioned API inference and persistent analytics support reproducible deployment and comparison of live and historical insights."}]},{slug:"electricity-bill-management-system",displayTitle:"PowerBill",subtitle:"Electricity Bill Management System",summary:"Connect customer and admin billing workflows through an Angular interface, Spring Boot services and REST APIs.",primaryTechnologies:["Java","Spring Boot","Angular","REST APIs","SQL"],visualIndex:3,title:"Electricity Bill Management System (PowerBill)",category:"Full-Stack Software Engineering",filter:"Web Development",short:"PowerBill",description:"A full-stack billing application with Customer and Admin modules, registration, bill generation and viewing, payment tracking, complaints and CRUD workflows.",technologies:["Java","Spring Boot","Angular","REST APIs","Eureka","SQL","H2","SCSS","Swagger"],status:"TCS Initial Learning Program",github:"https://github.com/harshawardhanchitnis/Project-FullStack-SpringBoot-Angular-Electricity-Bill-Management-System-PowerBill"},{slug:"rag-chatbot-for-pdf-documents",displayTitle:"RAG Chatbot",subtitle:"RAG Chatbot with Accuracy Evaluation",summary:"Answer PDF-based questions with semantic retrieval, then evaluate generated responses using ROUGE-1 and cosine similarity.",primaryTechnologies:["Python","FAISS","Sentence Transformers","DeepSeek","ROUGE-1"],visualIndex:4,title:"RAG Chatbot with Accuracy Evaluation",category:"Generative AI \xB7 Document Intelligence",filter:"AI/ML",short:"Document intelligence",description:"A document-based RAG chatbot combining PDF processing, semantic retrieval and DeepSeek / LLaMA-2 generation with explicit ROUGE-1 and cosine-similarity response evaluation.",technologies:["Python","RAG","FAISS","Sentence Transformers","DeepSeek","LLaMA-2","PDF Processing","ROUGE-1","Cosine Similarity"],status:"Explicit response evaluation",github:"https://github.com/harshawardhanchitnis/Project-Artificial-Intelligence-RAG-Chatbot-With-Accuracy-Evaluation"},{slug:"medical-insurance-cost-prediction",displayTitle:"Medical Insurance Prediction",subtitle:"Medical Insurance Cost Prediction",summary:"Compare Linear Regression and Random Forest models for insurance-cost estimation using structured data and explicit model evaluation.",primaryTechnologies:["Python","Scikit-learn","Pandas","Random Forest Regression","Linear Regression"],visualIndex:5,title:"Medical Insurance Cost Prediction",category:"Machine Learning \xB7 Regression",filter:"AI/ML",short:"Insurance cost modelling",description:"A regression project comparing Linear Regression and Random Forest Regression to estimate medical insurance costs using structured data and model evaluation.",technologies:["Python","Random Forest Regression","Linear Regression","Scikit-learn","Pandas","NumPy","Machine Learning"],status:"Best R\xB2: 0.838",github:"https://github.com/harshawardhanchitnis/Project-Machine-Learning-Medical-Insurance-Cost-Prediction"}];var s=class i{element=t(o);zone=t(a);observer;motion;animation;stopMotion=()=>{this.motion?.matches&&(this.animation?.cancel(),this.observer?.disconnect())};ngAfterViewInit(){this.zone.runOutsideAngular(()=>{this.motion=window.matchMedia?.("(prefers-reduced-motion: reduce)"),!(this.motion?.matches||typeof IntersectionObserver>"u")&&(this.motion?.addEventListener("change",this.stopMotion),this.observer=new IntersectionObserver(n=>{if(!n.some(c=>c.isIntersecting))return;this.observer?.disconnect();let e=this.element.nativeElement;!this.motion?.matches&&!e.contains(document.activeElement)&&(this.animation=e.animate?.([{opacity:0,transform:"translateY(16px)"},{opacity:1,transform:"none"}],{duration:420,easing:"cubic-bezier(.2,.7,.2,1)"}))},{threshold:.08}),this.observer.observe(this.element.nativeElement))})}ngOnDestroy(){this.observer?.disconnect(),this.animation?.cancel(),this.motion?.removeEventListener("change",this.stopMotion)}static \u0275fac=function(e){return new(e||i)};static \u0275dir=r({type:i,selectors:[["","appReveal",""]]})};export{l as a,s as b};
